  describe('editComment', () => {
    const minute = 60 * 1000;
    const now = new Date('2026-10-30T12:00:00.000Z');
    const slug = 'How-to-train-your-dragon';
    const commentId = 1;
    const userId = 123;

    const mockedAuthor = {
      username: 'RealWorld',
      bio: null,
      image: null,
      followedBy: [],
    };

    beforeEach(() => {
      jest.useFakeTimers().setSystemTime(now);
    });

    afterEach(() => {
      jest.useRealTimers();
    });

    test('should save the new body and set editedAt when the author edits within the window', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 5 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      const result = await editComment('edited body', slug, commentId, userId);

      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: { body: 'edited body', editedAt: now },
        }),
      );
      expect(result).toHaveProperty('body', 'edited body');
      expect(result).toHaveProperty('editedAt', now);
    });

    test('should only look up comments written by the current user on the article in the URL', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 1 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      await editComment('edited body', slug, commentId, userId);

      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId, authorId: userId, article: { slug } },
        }),
      );
    });

    test('should allow the edit at exactly 15 minutes after creation', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 15 * minute);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({
        id: commentId,
        createdAt,
        updatedAt: createdAt,
        body: 'edited body',
        editedAt: now,
        author: mockedAuthor,
      });

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).resolves.toHaveProperty(
        'editedAt',
        now,
      );
    });

    test('should refuse the edit after the 15 minute window', async () => {
      // Given
      const createdAt = new Date(now.getTime() - 15 * minute - 1);

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ createdAt });

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).rejects.toBeInstanceOf(
        HttpException,
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should refuse the edit when no comment of this user matches', async () => {
      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(editComment('edited body', slug, commentId, userId)).rejects.toBeInstanceOf(
        HttpException,
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should return 422 with the error body when the body is blank', async () => {
      // Then
      await expect(editComment('', slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 422,
        message: { errors: { body: ["can't be blank"] } },
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });
});

